h('14. Технологическая основа и ограничения')
table(['Компонент','Планируемое решение','Граница'],[['Язык','Java','Будущая реализация'],['Интерфейс','JavaFX','Окна, формы, таблицы'],['Хранение','SQLite через JDBC/слой доступа','Локальная автономная версия'],['Email','Сервисный слой и SMTP','События проектируются'],['Документация','Word/PDF, UML, Figma','Следующие результаты'],['Версионирование','Git/GitHub','Организация материалов']],[1.2,2.15,3.1],8.6)
p('Слоистая архитектура этапа 1 сохраняется: представление, прикладная логика, доменная модель, доступ к данным и инфраструктура. SRS задаёт ответственность и поведение, но не утверждает наличие этих компонентов в коде.')
h('14.1 Риски и ограничения',2); bullets(['локальная SQLite не обеспечивает общую работу нескольких компьютеров;','ОС и почтовая инфраструктура требуют уточнения;','две роли достаточны для базового сценария, администрирование — расширение;','без кода нельзя подтвердить производительность, безопасность и доставку писем.'])

